import{A as e}from"./chunks/ACardLinks.CaBYnln3.js";import{b as a}from"./chunks/place.Dz0_zc-L.js";import{C as u,o as s,c as n,j as t,a as o,E as p,F as b,B as d,b as y,k as m,a5 as D}from"./chunks/framework.CnBNXlt7.js";import"./chunks/index.B49wiAwd.js";const _={id:"去哪儿",tabindex:"-1"},f={href:"/trip/"},P=JSON.parse('{"title":"去哪儿","description":"","frontmatter":{},"headers":[],"relativePath":"trip/where/index.md","filePath":"trip/where/index.md","lastUpdated":1762096435000}'),h={name:"trip/where/index.md"},N=Object.assign(h,{setup(x){return(T,r)=>{const g=u("Badge");return s(),n("div",null,[t("h1",_,[r[0]||(r[0]=o("去哪儿",-1)),t("a",f,[p(g,{type:"tip",text:"旅行主页↗"})]),r[1]||(r[1]=o()),r[2]||(r[2]=t("a",{class:"header-anchor",href:"#去哪儿","aria-label":'Permalink to "去哪儿<a href="/trip/"><Badge type="tip" text="旅行主页↗" /></a>"'},"​",-1))]),r[3]||(r[3]=t("p",null,[o("走过蓝色星球，"),t("a",{href:"./../travelogue/"},"旅途记录(游记)"),o("，"),t("a",{href:"./../explore"},"探索(去过哪里)"),o("驻足，或是"),t("a",{href:"./../flying/"},"飞行"),o("，或是"),t("a",{href:"./../journey/"},"赶路"),o("……"),t("br"),o(" 本篇介绍各地的旅行推荐、美食推荐、玩法推荐。如果没有记录，则可能没去过，或是不推荐")],-1)),(s(!0),n(b,null,d(m(a),({title:l,items:i})=>(s(),y(e,{title:l,items:i},null,8,["title","items"]))),256)),r[4]||(r[4]=D('<h2 id="周末游" tabindex="-1"><strong>周末游</strong> <a class="header-anchor" href="#周末游" aria-label="Permalink to &quot;**周末游**&quot;">​</a></h2><p>浙江台州（临海+天台）<br><strong>标签：宋代长城 × 糯叽叽美食之都 × 佛宗道源</strong><br><strong>交通</strong>：杭州东→临海高铁约 <strong>1.5小时</strong>，自驾约3小时（适合高铁+当地租车/打车）。<br><strong>行程建议</strong>：<br><strong>Day1（临海：古街烟火气）</strong></p><ul><li>上午：高铁抵达临海，直奔 <strong>紫阳古街</strong>（浙江第一古街），吃海苔饼、乌饭麻糍、蛋清羊尾，逛人民银行旧址咖啡馆。</li><li>下午：爬 <strong>江南长城（台州府城墙）</strong>，从兴善门到揽胜门，敌台视野开阔，人少好拍。</li><li>晚上：入住临海市区或灵湖旁，夜游灵湖风景区。</li></ul><p><strong>Day2（天台：山水禅意）</strong></p><ul><li>上午：打车/租车赴 <strong>天台县</strong>（约1小时），游览 <strong>国清寺</strong>（隋代古刹，免门票，稻田环绕，清静脱俗）。</li><li>下午： <ul><li>体力好可选 <strong>天台山大瀑布</strong>（徒步观瀑，落差325米，似“中华第一高瀑”）。</li><li>或轻松逛 <strong>济公故居</strong>，午后高铁返杭（天台山站→杭州东约1小时）。<br><strong>特色</strong>：</li></ul></li><li>美食突出：临海是“小吃王国”，新荣记发源地，性价比高。</li><li>文化深厚：国清寺为佛教天台宗祖庭，无商业化气息。</li><li>人流量少：相比乌镇、西湖，此处更清净。</li></ul><p>安徽宣城（绩溪+歙县深渡）<br><strong>标签：徽杭古道起点 × 新安江山水画廊 × 人少原始</strong><br><strong>交通</strong>：杭州自驾约2.5小时（适合周五晚出发）。<br><strong>行程建议</strong>：</p><ul><li><strong>Day1</strong>：驱车至 <strong>绩溪龙川景区</strong>（胡氏宗祠+水街竹林），午后逛 <strong>仁里古村</strong>，宿绩溪。</li><li><strong>Day2</strong>：开车至 <strong>歙县深渡镇</strong>，乘船游 <strong>新安江山水画廊</strong>（3-4月油菜花，9-10月晒秋），午后返程。<strong>特色</strong>：比宏村更原始，船行江上如入水墨画。</li></ul><p>安徽黄山（徽州古城/宏村）<br><strong>标签：徽派建筑 × 山水画卷 × 写生圣地</strong><br><strong>交通</strong>：高铁杭州东→黄山北约1.5小时，转大巴至景区。<br><strong>行程建议</strong>：</p><ul><li><strong>Day1（徽州文化）</strong>： <ul><li>上午：高铁至黄山北，打车至徽州古城（歙县），参观许国石坊、斗山街，体验徽墨制作。</li><li>下午：前往宏村（约1小时车程），傍晚看南湖月沼倒影，宿宏村民宿。</li></ul></li><li><strong>Day2（自然奇观）</strong>： <ul><li>可选方案1：爬黄山（前山上后山下，重点玩迎客松、光明顶），但需早起且体力消耗大。</li><li>可选方案2：轻松版——游览碧山书局、西递古村，午后返程。<strong>特色</strong>：宏村晨雾如画，黄山云海震撼，适合摄影爱好者。</li></ul></li></ul><p>宁波（东钱湖/慈城古县城）<br><strong>标签：湖岸骑行 × 宋代遗风 × 海鲜盛宴</strong><br><strong>交通</strong>：高铁杭州东→宁波约1小时，自驾2小时。<br><strong>行程建议</strong>：</p><ul><li><strong>Day1（湖滨休闲）</strong>： <ul><li>上午：直达东钱湖，租自行车环湖骑行（推荐小普陀-南宋石刻公园段）。</li><li>下午：参观韩岭老街（美术馆+文创店），湖边品茶看日落。</li></ul></li><li><strong>Day2（古韵寻味）</strong>： <ul><li>上午：驱车至慈城古县城（约40分钟），逛孔庙、县衙，尝年糕饺。</li><li>下午：返回宁波市区，逛南塘老街买油攒子伴手礼，傍晚高铁返杭。<strong>特色</strong>：东钱湖有“西湖姊妹湖”之称，人少景美，海鲜新鲜价优。</li></ul></li></ul><p>丽水（浙南山水天花板）</p><p><strong>标签：云海梯田 × 古寨秘境 × 摄影圣地</strong><br><strong>交通</strong>：杭州高铁至丽水站约1.5小时，建议到站后租车自驾（景点分散）。<br><strong>推荐路线：云和梯田-松阳古村-古堰画乡</strong><br><strong>行程建议</strong>：</p><ul><li><strong>Day1（云端漫步）</strong>： <ul><li>上午：高铁至丽水，租车直奔 <strong>云和梯田</strong>（九曲云环观景台看日出云海，白银谷徒步古寨坑根村）。</li><li>下午：驱车至 <strong>松阳县</strong>（约1.5小时），住 <strong>陈家铺村</strong>（悬崖上的先锋书店、飞茑集民宿）。</li></ul></li><li><strong>Day2（古村探秘）</strong>： <ul><li>上午：逛松阳古村—— <strong>杨家堂村</strong>（金色布达拉宫）、 <strong>松庄村</strong>（石拱桥溪流，600年古村）。</li><li>下午：赴 <strong>古堰画乡</strong>（瓯江帆影、千年通济堰），傍晚返丽水站还车返杭。<strong>特色</strong>：中国最美乡村集结地，适合放空、摄影，春夏绿意盎然，秋季稻浪金黄。</li></ul></li></ul><p>温州（山海奇观+江湖气）<br><strong>标签：百岛之城 × 楠溪江诗意 × 小吃狂飙</strong><strong>交通</strong>：杭州高铁至温州南约2.5小时，建议搭配租车。 <strong>推荐路线：楠溪江-洞头岛-温州市区</strong><strong>行程建议</strong>：</p><ul><li><strong>Day1（江风古韵）</strong>： <ul><li>上午：高铁至温州南，租车直奔 <strong>楠溪江</strong>（石桅岩徒步、竹筏漂流，尝岭上人家烤全羊）。</li><li>下午：游览 <strong>丽水街</strong>、 <strong>苍坡古村</strong>，宿永嘉县。</li></ul></li><li><strong>Day2（海岛日记）</strong>： <ul><li>上午：驱车至 <strong>洞头岛</strong>（约1.5小时），打卡小洱海纪念碑、七彩油画村。</li><li>下午：海鲜大排档（推荐葱油蛏子、猫耳朵），返温州市区逛五马街，傍晚高铁回杭。<strong>特色</strong>：集江、山、海于一体，小吃有灯盏糕、猪脏粉、鱼丸汤，吃货天堂。</li></ul></li></ul><p>上饶（婺源非景区段+三清山）<br><strong>标签：徽派村落 × 道教仙峰 × 秋色封神</strong><strong>交通</strong>：杭州高铁至上饶约1.5小时，转大巴/租车。 <strong>行程建议</strong>：</p><ul><li><strong>Day1</strong>：高铁至上饶，租车赴 <strong>婺源</strong>（避开篁岭人流，推荐 <strong>察关村</strong>水牛桥、 <strong>虹关村</strong>古樟、 <strong>石城</strong>晨雾）。</li><li><strong>Day2</strong>：登 <strong>三清山</strong>（西海岸栈道看云海，巨蟒出山、女神峰），傍晚返程。<strong>特色</strong>：秋日红枫、晒秋绝美，三清山奇石云海不输黄山。</li></ul><p>抚州（资深古镇+才子文化）<br><strong>标签：王安石故里 × 明清老街 × 冷门无人</strong><strong>交通</strong>：杭州高铁至抚州约3小时（适合3天周末）。 <strong>行程建议</strong>：</p><ul><li><strong>Day1</strong>：游 <strong>文昌里历史文化街</strong>（汤显祖墓、古戏台），夜宿 <strong>金溪县</strong>。</li><li><strong>Day2</strong>：探 <strong>竹桥古村</strong>（《爸爸去哪儿》拍摄地）、 <strong>流坑古村</strong>（千年科举文化聚落），返抚州市区。<strong>特色</strong>：文化底蕴深厚，几乎无游客，适合历史爱好者。<br> 宜春（温汤古镇**+明月山）**<br><strong>标签：富硒温泉 × 森林氧吧 × 禅意养生****交通</strong>：杭州高铁至宜春约4小时（建议周五晚出发）。<strong>行程建议</strong>：</li><li><strong>Day1</strong>：高铁至宜春，夜泡 <strong>温汤古镇</strong>古井温泉（免费足浴池+付费温泉酒店）。</li><li><strong>Day2</strong>：爬 <strong>明月山</strong>（云谷飞瀑、月亮湖），下午返程。<strong>特色</strong>：温泉水质全国顶尖，适合秋冬疗愈之旅。</li></ul>',20))])}}});export{P as __pageData,N as default};
